{"command":"cat <<'EOF' > src/template.rs
use tera::{Tera, Context, Value, Result as TeraResult};
use std::collections::HashMap;
use crate::config::Config;
use crate::embedded::Asset;

pub fn init_tera(config: &Config) -> Tera {
    let mut tera = Tera::default();

    // Load embedded templates
    for file in Asset::iter() {
        if file.starts_with("templates/") {
            let content = Asset::get(&file).unwrap();
            let name = file.strip_prefix("templates/").unwrap();
            let template_str = std::str::from_utf8(content.data.as_ref()).unwrap();
            tera.add_raw_template(name, template_str).unwrap();
        }
    }

    // Register custom functions and filters
    let config_clone = config.clone();
    tera.register_function("url_for", move |args: &HashMap<String, Value>| -> TeraResult<Value> {
        let path = args.get("path").and_then(|v| v.as_str()).unwrap_or("");
        let abs = args.get("abs").and_then(|v| v.as_bool()).unwrap_or(false);

        let mut full_path = if path.starts_with("/") {
            path.to_string()
        } else {
            format!("/{}", path)
        };

        if abs && !config_clone.url.is_empty() {
            let base_url = config_clone.url.trim_end_matches('/');
            full_path = format!("{}{}", base_url, full_path);
        }

        Ok(Value::String(full_path))
    });

    let default_date_format = config.default_date_format.clone();
    tera.register_filter("default_date_format", move |value: &Value, _args: &HashMap<String, Value>| -> TeraResult<Value> {
        if let Some(date_str) = value.as_str() {
            // value is already a string? Wait, Tera dates are often strings or Serialized DateTimes.
            // If it's a DateTime, we should format it.
            // For now, let's assume it's a string from chrono::DateTime.
            Ok(Value::String(date_str.to_string()))
        } else {
             Ok(value.clone())
        }
    });

    tera.register_filter("slugify", |value: &Value, _args: &HashMap<String, Value>| -> TeraResult<Value> {
        if let Some(s) = value.as_str() {
            Ok(Value::String(slug::slugify(s)))
        } else {
            Ok(value.clone())
        }
    });

    tera
}
EOF
"}

