{"command":"cat <<'EOF' > src/site.rs
use crate::config::{Config, Author};
use crate::content::{Content, parse_markdown};
use crate::template::init_tera;
use crate::embedded::Asset;
use std::path::{Path, PathBuf};
use std::fs;
use tera::{Context, Tera};
use anyhow::Result;
use walkdir::WalkDir;
use std::collections::HashMap;

pub struct Site {
    pub config: Config,
    pub input_folder: PathBuf,
    pub output_folder: PathBuf,
    pub content: Vec<Content>,
    pub pages: Vec<Content>,
    pub tera: Tera,
}

impl Site {
    pub fn new(input: PathBuf, output: PathBuf, config: Config) -> Self {
        let tera = init_tera(&config);
        Self {
            config,
            input_folder: input,
            output_folder: output,
            content: Vec::new(),
            pages: Vec::new(),
            tera,
        }
    }

    pub fn load_content(&mut self) -> Result<()> {
        let content_path = self.input_folder.join(&self.config.content_path);
        if !content_path.exists() {
            // If content_path doesn't exist, use input_folder directly? 
            // The help said: "no need to change this if your markdown files are in input_folder directly"
            // But usually it looks for content/ first.
        }

        let base_path = if content_path.exists() { &content_path } else { &self.input_folder };

        for entry in WalkDir::new(base_path).into_iter().filter_map(|e| e.ok()) {
            if entry.file_type().is_file() && entry.path().extension().map_or(false, |ext| ext == "md") {
                let filename = entry.file_name().to_str().unwrap();
                if filename.starts_with('_') {
                    continue;
                }

                let mut content = parse_markdown(entry.path(), base_path)?;

                // Determine if it is a page or a post.
                // In Marmite, how is it determined? 
                // Maybe by a flag in front-matter or by being in a specific folder.
                // Let's assume posts by default.

                self.content.push(content);
            }
        }

        // Sort content by date descending
        self.content.sort_by(|a, b| b.date.cmp(&a.date));

        Ok(())
    }

    pub fn generate(&mut self) -> Result<()> {
        if !self.output_folder.exists() {
            fs::create_dir_all(&self.output_folder)?;
        }

        // Copy static assets
        self.copy_static_assets()?;

        // Render posts
        for content in &self.content {
            self.render_content(content)?;
        }

        // Render index
        self.render_index()?;

        // Render other list pages (tags, archive, etc.)
        self.render_lists()?;

        // Generate RSS
        self.generate_rss()?;

        // Generate sitemap
        self.generate_sitemap()?;

        // Generate urls.json
        self.generate_urls_json()?;

        Ok(())
    }

    fn copy_static_assets(&self) -> Result<()> {
        let static_output = self.output_folder.join("static");
        if !static_output.exists() {
            fs::create_dir_all(&static_output)?;
        }

        // Copy embedded assets
        for file in Asset::iter() {
            if file.starts_with("static/") {
                let content = Asset::get(&file).unwrap();
                let output_path = self.output_folder.join(&file);
                if let Some(parent) = output_path.parent() {
                    fs::create_dir_all(parent)?;
                }
                fs::write(output_path, content.data)?;
            }
        }

        // Copy user static assets if they exist
        let user_static = self.input_folder.join(&self.config.static_path);
        if user_static.exists() {
            // copy recursively
