{"command":"cat <<'EOF' > src/site.rs
use crate::config::{Config};
use crate::content::{Content, parse_markdown};
use crate::template::init_tera;
use crate::embedded::Asset;
use std::path::{PathBuf};
use std::fs;
use tera::{Context, Tera};
use anyhow::Result;
use walkdir::WalkDir;

pub struct Site {
    pub config: Config,
    pub input_folder: PathBuf,
    pub output_folder: PathBuf,
    pub content: Vec<Content>,
    pub pages: Vec<Content>,
}

impl Site {
    pub fn new(input: PathBuf, output: PathBuf, config: Config) -> Self {
        Self {
            config,
            input_folder: input,
            output_folder: output,
            content: Vec::new(),
            pages: Vec::new(),
        }
    }

    pub fn load_content(&mut self) -> Result<()> {
        let content_path = self.input_folder.join(&self.config.content_path);
        let base_path = if content_path.exists() { &content_path } else { &self.input_folder };

        for entry in WalkDir::new(base_path).into_iter().filter_map(|e| e.ok()) {
            if entry.file_type().is_file() && entry.path().extension().map_or(false, |ext| ext == "md") {
                let filename = entry.file_name().to_str().unwrap();
                if filename.starts_with('_') {
                    continue;
                }

                let mut content = parse_markdown(entry.path(), base_path)?;
                // Determine if page or post. For now, all are posts.
                self.content.push(content);
            }
        }

        self.content.sort_by(|a, b| b.date.cmp(&a.date));

        Ok(())
    }

    pub fn generate(&self) -> Result<()> {
        if !self.output_folder.exists() {
            fs::create_dir_all(&self.output_folder)?;
        }

        self.copy_static_assets()?;

        let tera = init_tera(&self.config, self.content.clone());

        for content in &self.content {
            self.render_content(&tera, content)?;
