use serde::{Deserialize, Serialize};
use std::path::Path;
use chrono::{DateTime, Utc, NaiveDate};
use pulldown_cmark::{Parser, Options, html};
use regex::Regex;
use anyhow::Result;

#[derive(Debug, Serialize, Deserialize, Clone)]
pub struct ContentFrontMatter {
    pub title: Option<String>,
    pub date: Option<DateTime<Utc>>,
    pub tags: Option<Vec<String>>,
    pub authors: Option<Vec<String>>,
    pub stream: Option<String>,
    pub series: Option<String>,
    pub pinned: Option<bool>,
    pub extra: Option<serde_yaml::Value>,
    pub description: Option<String>,
    pub banner_image: Option<String>,
    pub card_image: Option<String>,
    pub toc: Option<bool>,
}

#[derive(Debug, Serialize, Clone)]
pub struct Content {
    pub slug: String,
    pub title: String,
    pub date: Option<String>, // ISO string
    pub tags: Vec<String>,
    pub authors: Vec<String>,
    pub stream: Option<String>,
    pub series: Option<String>,
    pub pinned: bool,
    pub html: String,
    pub excerpt: String,
    pub description: Option<String>,
    pub banner_image: Option<String>,
    pub card_image: Option<String>,
    pub toc: Option<String>,
    pub is_page: bool,
    pub extra: serde_yaml::Value,
    pub source_path: String,
}

pub fn parse_markdown(path: &Path, content_path: &Path) -> Result<Content> {
    let file_content = std::fs::read_to_string(path)?;
    let mut title = None;
    let mut date_dt: Option<DateTime<Utc>> = None;
    let mut tags = Vec::new();
    let mut authors = Vec::new();
    let mut stream = None;
    let mut series = None;
    let mut pinned = false;
    let mut extra = serde_yaml::Value::Null;
    let mut description = None;
    let mut banner_image = None;
    let mut card_image = None;
    let mut toc_enabled = false;
    let mut is_page = false;

    let markdown = if file_content.starts_with("---") {
        if let Some(end) = file_content[3..].find("---") {
            let fm_res: Result<ContentFrontMatter, _> = serde_yaml::from_str(&file_content[3..end + 3]);
            if let Ok(fm) = fm_res {
                title = fm.title;
                date_dt = fm.date;
                tags = fm.tags.unwrap_or_default();
                authors = fm.authors.unwrap_or_default();
                stream = fm.stream;
                series = fm.series;
                pinned = fm.pinned.unwrap_or(false);
                extra = fm.extra.unwrap_or(serde_yaml::Value::Null);
                description = fm.description;
                banner_image = fm.banner_image;
                card_image = fm.card_image;
                toc_enabled = fm.toc.unwrap_or(false);
                &file_content[end + 6..]
            } else {
                &file_content
            }
        } else {
            &file_content
        }
    } else {
        &file_content
    };

    if title.is_none() {
        if let Some(line) = markdown.lines().find(|l| l.starts_with("# ")) {
            title = Some(line[2..].trim().to_string());
        }
    }

    let filename = path.file_name().unwrap().to_str().unwrap();
    if date_dt.is_none() {
        let re = Regex::new(r"(\d{4}-\d{2}-\d{2})").unwrap();
        if let Some(caps) = re.captures(filename) {
            let date_str = caps.get(1).unwrap().as_str();
            if let Ok(d) = NaiveDate::parse_from_str(date_str, "%Y-%m-%d") {
                date_dt = Some(DateTime::<Utc>::from_utc(d.and_hms(0, 0, 0), Utc));
            }
        }
    }

    let slug_full = filename.strip_suffix(".md").unwrap().to_string();
    let re_date_prefix = Regex::new(r"^\d{4}-\d{2}-\d{2}-").unwrap();
    let slug = re_date_prefix.replace(&slug_full, "").to_string();

    let mut options = Options::all();
    let parser = Parser::new_ext(markdown, options);
    let mut html_output = String::new();
    html::push_html(&mut html_output, parser);

    if title.is_none() {
        title = Some(slug.clone());
    }

    let excerpt = html_output.chars().take(200).collect();

    Ok(Content {
        slug,
        title: title.unwrap(),
        date: date_dt.map(|dt| dt.to_rfc3339()),
        tags,
        authors,
        stream,
        series,
        pinned,
        html: html_output,
        excerpt,
        description,
        banner_image,
        card_image,
        toc: None,
        is_page,
        extra,
        source_path: path.strip_prefix(content_path).unwrap_or(path).to_str().unwrap().to_string(),
    })
}
EOF
"}

