import os
import sys
import re
import json
import argparse
import base64
from datetime import datetime

EMBEDDED_ASSETS = {}
SAMPLE_FILES = {}

def parse_simple_yaml(text):
    data = {}
    if not text: return data
    for line in text.split('\n'):
        line = line.split('#')[0].strip() # remove comments
        if ':' in line:
            k, v = line.split(':', 1)
            k = k.strip()
            v = v.strip().strip('"\'')
            if v.startswith('[') and v.endswith(']'):
                v = [i.strip().strip('"\'') for i in v[1:-1].split(',')]
            elif v.lower() == 'true': v = True
            elif v.lower() == 'false': v = False
            elif v.isdigit(): v = int(v)
            data[k] = v
    return data

class SimpleTemplate:
    def __init__(self, templates, config):
        self.templates = templates
        self.config = config

    def render(self, name, context):
        text = self.templates.get(f"templates/{name}", "")
        # Handle extends
        m = re.search(r'{%\s*extends\s*"([^"]+)"\s*%}', text)
        if m:
            parent_name = m.group(1)
            parent_text = self.templates.get(f"templates/{parent_name}", "")
            blocks = re.findall(r'{%\s*block\s+(\w+)\s*%}(.*?){%\s*endblock\s*%}', text, re.DOTALL)
            for bname, bcontent in blocks:
                parent_text = re.sub(rf'{{%\s*block\s+{bname}\s*%}}.*?{{%\s*endblock\s*%}}', 
                                   bcontent.replace('\\', '\\\\'), parent_text, flags=re.DOTALL)
            text = parent_text

        # Handle includes
        for _ in range(5): # Limit recursion
            m = re.search(r'{%\s*include\s*"([^"]+)"\s*(?:ignore missing)?\s*%}', text)
            if not m: break
            inc_name = m.group(1)
            inc_text = self.templates.get(f"templates/{inc_name}", "")
            text = text[:m.start()] + inc_text + text[m.end():]

        # Handle simple variables
        def repl(m):
            expr = m.group(1).strip()
            # Split filters
            expr = expr.split('|')[0].strip()
            # Evaluate expression
            if expr == "site.name": return self.config.get('name', 'Home')
            if expr == "site.tagline": return self.config.get('tagline', '')
            if expr == "site.footer": return self.config.get('footer', '')
            if expr == "content.title": return context.get('content', {}).get('title', '')
            if expr == "content.html": return context.get('content', {}).get('html', '')
            if expr == "content.slug": return context.get('content', {}).get('slug', '')
            if expr == "announce": return context.get('announce', '')
            if expr == "hero": return context.get('hero', '')
            # Handle url_for
            if expr.startswith('url_for('):
                m_url = re.search(r"path=['\"]([^'\"]*)['\"]", expr)
                if m_url:
                    p = m_url.group(1)
                    if not p.startswith('/'): p = '/' + p
                    return p
            return ""

        text = re.sub(r'{{(.*?)}}', repl, text)
        text = re.sub(r'{%.*?%}', '', text)
        return text

def parse_markdown(text):
    fm = {}
    if text.startswith('---'):
        parts = text.split('---', 2)
        if len(parts) >= 3:
            fm = parse_simple_yaml(parts[1])
            text = parts[2]

    html = text
    html = re.sub(r'^# (.*)$', r'<h1>\1</h1>', html, flags=re.MULTILINE)
    html = re.sub(r'^## (.*)$', r'<h2>\1</h2>', html, flags=re.MULTILINE)
    html = re.sub(r'\[([^\]]+)\]\(([^)]+)\)', r'<a href="\2">\1</a>', html)
    # Very simple paragraph logic
    html = "\n".join([f"<p>{l}</p>" if l.strip() and not l.startswith('<h') else l for l in html.split('\n')])

    title = fm.get('title')
    if not title:
        m = re.search(r'<h1>(.*?)</h1>', html)
        if m: title = m.group(1)

    return fm, html, title

def main():
    parser = argparse.ArgumentParser(add_help=False)
    parser.add_argument('input_folder', nargs='?')
    parser.add_argument('output_folder', nargs='?')
    parser.add_argument('-V', '--version', action='store_true')
    parser.add_argument('--init-site', action='store_true')
    parser.add_argument('--init-templates', action='store_true')
    args, unknown = parser.parse_known_args()

    if args.version:
        print("marmite 0.2.7")
        return

    if args.init_site and args.input_folder:
        for path, b64 in SAMPLE_FILES.items():
            out_path = os.path.join(args.input_folder, path)
            os.makedirs(os.path.dirname(out_path), exist_ok=True)
            with open(out_path, 'wb') as f:
                f.write(base64.b64decode(b64))
        print(f"Site initialized in {args.input_folder}")
        return

    if not args.input_folder:
        return

    out_folder = args.output_folder or os.path.join(args.input_folder, 'site')
    os.makedirs(out_folder, exist_ok=True)

    # Load config
    cfg_path = os.path.join(args.input_folder, 'marmite.yaml')
    config = {}
    if os.path.exists(cfg_path):
        with open(cfg_path, 'r') as f:
            config = parse_simple_yaml(f.read())

    # Get assets and templates
    templates = {}
    for path, b64 in EMBEDDED_ASSETS.items():
        if path.startswith('static/'):
            out_path = os.path.join(out_folder, path)
            os.makedirs(os.path.dirname(out_path), exist_ok=True)
            with open(out_path, 'wb') as f:
                f.write(base64.b64decode(b64))
        elif path.startswith('templates/'):
            templates[path] = base64.b64decode(b64).decode('utf-8')

    engine = SimpleTemplate(templates, config)

    # Special files
    specials = {}
    for s in ['_announce.md', '_hero.md', '_footer.md']:
        p = os.path.join(args.input_folder, 'content', s)
        if not os.path.exists(p): p = os.path.join(args.input_folder, s)
        if os.path.exists(p):
            with open(p, 'r') as f:
                _, html, _ = parse_markdown(f.read())
                specials[s[1:-3]] = html

    # Parse content
    content_list = []
    content_dir = os.path.join(args.input_folder, 'content')
    if not os.path.exists(content_dir): content_dir = args.input_folder

    for f in os.listdir(content_dir):
        if f.endswith('.md') and not f.startswith('_'):
            with open(os.path.join(content_dir, f), 'r') as fd:
                fm, html, title = parse_markdown(fd.read())
                slug = f[:-3]
                # remove date prefix
                slug = re.sub(r'^\d{4}-\d{2}-\d{2}-', '', slug)
                c = {'title': title, 'html': html, 'slug': slug, 'fm': fm}
                content_list.append(c)

                # Render post
                ctx = {**specials, 'content': c}
                rendered = engine.render('content.html', ctx)
                with open(os.path.join(out_folder, f'{slug}.html'), 'w') as outf:
                    outf.write(rendered)

    # Render index
    ctx = {**specials, 'content_list': content_list}
    rendered = engine.render('list.html', ctx)
    with open(os.path.join(out_folder, 'index.html'), 'w') as outf:
        outf.write(rendered)

    print(f"Site generated at {out_folder}/")

if __name__ == "__main__":
    main()
