import base64
import os

def embed_dir(directory):
    assets = {}
    if not os.path.exists(directory): return assets
    for root, dirs, files in os.walk(directory):
        for file in files:
            path = os.path.join(root, file)
            rel_path = os.path.relpath(path, directory)
            with open(path, 'rb') as f:
                assets[rel_path] = base64.b64encode(f.read()).decode('ascii')
    return assets

embedded = embed_dir('src/embedded')
sample_files = embed_dir('sample-files')

with open('marmite_template.py', 'r') as f:
    code = f.read()

code = code.replace('EMBEDDED_ASSETS = {}', f'EMBEDDED_ASSETS = {repr(embedded)}')
code = code.replace('SAMPLE_FILES = {}', f'SAMPLE_FILES = {repr(sample_files)}')

with open('executable', 'w') as f:
    f.write('#!/usr/bin/env python3\n')
    f.write(code)
os.chmod('executable', 0o755)
